js.text:

function grid$dmnvApprove(f){
  this.constructor(f);
}
grid$dmnvApprove.prototype = new DirEvent();
grid$dmnvApprove.prototype.afterInit = function(renderType){
  var p = this._dir;
  if (p.options._status == 3 || options._status == 5 || options._status == 7) p.find(".toolbar-approve").attr('title', p.msg('approve'))
  else if (p.options._status == 9) p.find(".toolbar-approve").attr('title', p.msg('undo'))
  else p.find(".toolbar-approve").attr('title', p.msg('open'));
  p.find(".toolbar-cancel").css("display", (p.options._status == 1)?"":"none")
}
grid$dmnvApprove.prototype.beforeButtonGridClick = function (ma_nv, gindex) {

  var msg, p = this._dir, g = p.grid(gindex), dt = g.data, fees = p.selectedItems(), xstatus = p.options._xstatus;
  switch (ma_nv) {

    case 'approve':
      msg = (xstatus == 3 || xstatus == 5 || xstatus == 7 )? p.msg('msg1'): (xstatus == 9)? p.msg('msg2'):p.msg('msg3');
      if (fees.count() > 0)
        $.question(msg, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v){
            p.request('Approve', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        });
      return false;
      break;

    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}

dir.script:



declare @deststatus int, @uid int, @dduyet date
set @deststatus = case @xstatus when 5 then 9 else 9 end --else 9 - Huy thi tra ve duyet
set @uid = case when @xstatus = 3 then @@userId when @xstatus = 5 then @@userId when @xstatus = 7 then @@userId else 0 end
set @dduyet = case when @xstatus = 3 then getdate() when @xstatus = 5 then getdate() when @xstatus = 7 then getdate() else null end

update dmnv set xstatus = @deststatus, user_id_duyet = @uid, ngay_duyet = @dduyet, ngay_kt_lv = @dduyet where ma_nv in (select ma_nv from @tblKeys)

DECLARE @i AS INT = 1;
DECLARE @count_row_stt INT;

-- Tạo bảng tạm để lưu trữ dữ liệu từ #data với thêm cột row_stt
SELECT *, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS row_stt
INTO #data_with_row
FROM @tblKeys

-- Đếm số lượng hàng trong #data_with_row
SELECT @count_row_stt = COUNT(*) FROM #data_with_row;
--update dmnv set xstatus = @deststatus, user_id_duyet = @uid, ngay_duyet = @dduyet, ngay_kt_lv = @dduyet where ma_nv in (select ma_nv from @tblKeys)
WHILE @i <= @count_row_stt 
BEGIN
    DECLARE @ma_nv_del VARCHAR(32) = '';
	SELECT @ma_nv_del = ma_nv FROM #data_with_row  WHERE row_stt = @i;
    -- Gọi stored procedure truyền mã nv cần xóa vào
    EXEC [ISWIFTStoredSplitGroupName] @ma_nv_del, ''

    -- Tăng giá trị của @i để lặp qua hàng tiếp theo
    SET @i = @i + 1;
END;
DROP TABLE IF EXISTS #data_with_row;

select '' as message, '$Processed' as toast




    &VoucherJSLoading;
